use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's `HTTPClient` handle is granted. A URL outside this set
/// would trap at the capability boundary, so it is reported as a failure
/// instead of fetched; one bad subscription must not fail the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Key under which each call's input is recorded in the shared store.
const LAST_INPUT_KEY: &str = "last-input";

struct Node;

/// Encode a string as a JSON string literal.
fn json_string(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Serialise the subscription list as `{"urls":[...]}`.
fn encode_input(urls: &[String]) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        json_string(url, &mut out);
    }
    out.push_str("]}");
    out
}

/// Extract the lowercased host of an http(s) URL, or explain why it cannot be
/// fetched. Conservative: anything ambiguous is rejected rather than guessed.
fn host_of(url: &str) -> Result<String, String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if let Some(r) = lower.strip_prefix("https://") {
        r
    } else if let Some(r) = lower.strip_prefix("http://") {
        r
    } else {
        return Err("unsupported URL scheme (expected http or https)".to_string());
    };

    let authority_end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];

    if authority.contains('@') {
        return Err("URLs with user info are not fetched".to_string());
    }
    if authority.starts_with('[') {
        return Err("IP-literal hosts are not permitted".to_string());
    }

    let host = match authority.find(':') {
        Some(i) => &authority[..i],
        None => authority,
    };
    let host = host.strip_suffix('.').unwrap_or(host);

    if host.is_empty() {
        return Err("URL has no host".to_string());
    }
    Ok(host.to_string())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call in the shared store.
        state_rw::put(LAST_INPUT_KEY, &encode_input(&subscriptions.urls));

        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            let host = match host_of(&url) {
                Ok(h) => h,
                Err(error) => {
                    failures.push(FetchFailure { url, error });
                    continue;
                }
            };

            if !ALLOWED_HOSTS.contains(&host.as_str()) {
                failures.push(FetchFailure {
                    error: format!("host '{}' is not in this node's HTTP allowlist", host),
                    url,
                });
                continue;
            }

            match http_client::fetch(url.trim()) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
